#!/usr/bin/env node
// scaffold-component-tests.js — v73 emits a Vitest+RTL smoke test per
// scaffolded page under app/pages/. Tests assert page renders without
// crashing + key data-testids are present + loading/empty/error states
// behave correctly.
//
// Detects scaffolded pages by their generation comment ("Generated by
// scaffold-*-pages"). Skips LLM-authored pages (different patterns).
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-component-tests --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function walk(dir, out) {
  if (!fs.existsSync(dir)) return;
  fs.readdirSync(dir, { withFileTypes: true }).forEach(function (e) {
    var f = path.join(dir, e.name);
    if (e.isDirectory()) walk(f, out);
    else if (e.isFile() && /Page\.tsx$/.test(e.name)) out.push(f);
  });
}

function pickPrimaryTestId(content) {
  // Look for the first `data-testid="<page-slug>-page"` style id which
  // every scaffold-*-pages template emits at the root element.
  var m = content.match(/data-testid="([a-z][a-z0-9-]*-page)"/);
  return m ? m[1] : null;
}

function renderTest(pageFile, pageRel, primaryTestId) {
  // Build import path from tests/components/ → app/pages/
  var name = path.basename(pageFile, '.tsx');
  var importRel = '~/' + pageRel.replace(/^app\//, '').replace(/\.tsx$/, '');
  return [
    "/** Generated by scaffold-component-tests for " + pageRel + " */",
    "import { describe, expect, it } from 'vitest';",
    "import { render, screen } from '@testing-library/react';",
    "import { MemoryRouter } from 'react-router';",
    "import { Provider } from 'react-redux';",
    "import { configureStore } from '@reduxjs/toolkit';",
    "import { I18nextProvider } from 'react-i18next';",
    "import i18n from '~/i18n';",
    "import Page from '" + importRel + "';",
    "",
    "function wrap(ui: React.ReactNode) {",
    "  const store = configureStore({ reducer: () => ({ auth: { user: null } }) });",
    "  return (",
    "    <Provider store={store}>",
    "      <I18nextProvider i18n={i18n}>",
    "        <MemoryRouter>{ui}</MemoryRouter>",
    "      </I18nextProvider>",
    "    </Provider>",
    "  );",
    "}",
    "",
    "describe('" + name + "', () => {",
    "  it('renders without crashing', () => {",
    "    expect(() => render(wrap(<Page />))).not.toThrow();",
    "  });",
    "",
    primaryTestId
      ? "  it('renders root data-testid (" + primaryTestId + ")', () => {\n" +
        "    render(wrap(<Page />));\n" +
        "    const root = screen.queryByTestId('" + primaryTestId + "') ||\n" +
        "                 screen.queryByTestId('" + primaryTestId.replace(/-page$/, '-loading') + "') ||\n" +
        "                 screen.queryByTestId('" + primaryTestId.replace(/-page$/, '-error') + "');\n" +
        "    expect(root).toBeTruthy();\n" +
        "  });"
      : "  it.skip('no root data-testid detected', () => {});",
    "});",
    "",
  ].join('\n');
}

function main() {
  var args = parseArgs(process.argv);
  var pagesDir = path.join(args.target, 'app/pages');
  if (!fs.existsSync(pagesDir)) {
    console.log('scaffold-component-tests: no app/pages dir — skipping');
    return;
  }
  var pages = [];
  walk(pagesDir, pages);

  var testsDir = path.join(args.target, 'tests/components');
  if (!args.dryRun) fs.mkdirSync(testsDir, { recursive: true });

  var written = 0;
  var skipped = 0;
  for (var i = 0; i < pages.length; i++) {
    var pf = pages[i];
    var content = fs.readFileSync(pf, 'utf-8');
    // Only test scaffolded pages — LLM ones have unpredictable shape
    if (!/Generated by scaffold-/.test(content)) { skipped++; continue; }
    var pageRel = path.relative(args.target, pf);
    var primary = pickPrimaryTestId(content);
    var testName = path.basename(pf, '.tsx') + '.test.tsx';
    var dst = path.join(testsDir, testName);
    if (fs.existsSync(dst)) { skipped++; continue; }
    var spec = renderTest(pf, pageRel, primary);
    if (args.dryRun) {
      console.log('  [dry] would write ' + path.relative(args.target, dst));
    } else {
      fs.writeFileSync(dst, spec);
    }
    written++;
  }
  console.log('scaffold-component-tests: wrote ' + written + ' tests, skipped ' + skipped + ' (LLM-authored or existing)');
}

main();
